<?php
require_once 'connection/config.php';
require_once '__init.php';
require_once 'inc/functions.php';
require_once 'inc/RevisionPlan.php';
require_once 'inc/StudentCourseAccess.php';
require_once 'inc/StudentResourceGateway.php';

$pageName = 'revision_plans';
$conn = db();
$userId = student_course_access_student_id($conn, $_SESSION['username'] ?? '');
$assignmentId = (int) ($assignmentId ?? 0);
$context = $userId > 0 ? mmh_revision_assignment_context($conn, $assignmentId, (int) $userId) : null;
if (!$context) { http_response_code(404); exit('Revision Plan not found.'); }
$assignment = $context['assignment'];
$days = $context['days'];
$base = rtrim((string) $baseUrl, '/');
$esc = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$resources = [];
foreach ((array) ($context['version']['resources'] ?? []) as $resource) $resources[(int) $resource['id']] = $resource;
$resourceUrl = static function (int $resourceId, int $requirementId = 0) use ($base, $assignmentId): string { $url = $base . '/user/revision-resource/' . $assignmentId . '/' . $resourceId; return $requirementId > 0 ? $url . '?requirement=' . $requirementId : $url; };
$itemUrl = static function (string $itemId, int $requirementId) use ($base, $assignmentId, $assignment): string { return mmh_student_resource_url($base, (string) $assignment['course_id'], $itemId, ['revision_assignment_id' => $assignmentId, 'revision_requirement_id' => $requirementId]); };
$metatags = $metatags ?? ''; $keywords = $keywords ?? ''; $openGraph = $openGraph ?? ''; $schema = $schema ?? '';
?>
<!doctype html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $esc($assignment['title']) ?> | Your Plans</title><?php include 'layouts/user/header.php'; ?><link rel="stylesheet" href="<?= $esc($base . '/resources/css/revision-plans.css') ?>"></head>
<body class="body ds-bg-primary" style="margin-top:65px"><div id="app"><div id="body-overlay"></div><?php include 'layouts/user/aside.php'; ?><main class="revision-student-page"><header class="revision-student-header"><div class="container"><a class="revision-student-back" href="<?= $esc($base . '/user/revision-plans') ?>"><span class="fas fa-arrow-left" aria-hidden="true"></span> Your Plans</a><span class="revision-student-eyebrow"><?= $esc($assignment['course_title']) ?></span><h1><?= $esc($assignment['title']) ?></h1><p>Read-only revision plan · sequential days begin <?= $esc(date('j M Y', strtotime((string) $assignment['start_date']))) ?>.</p></div><div class="container p-0"><div class="col-12 row user-menu"><nav class="navbar navbar-expand-lg navbar-light ds-surface-muted"><div class="container-fluid p-0"><?php include 'layouts/user/main-nav.php'; ?></div></nav></div></div></header><section class="revision-student-shell container"><div class="revision-plan-timeline"><aside class="revision-day-list" aria-label="Plan days"><h2>Plan timeline</h2><?php foreach ($days as $day): ?><a class="revision-day-link <?= $day['availability'] === 'today' ? 'is-today' : '' ?> <?= !$day['accessible'] ? 'is-locked' : '' ?>" href="#day-<?= (int) $day['absolute_day_number'] ?>"><span>Day <?= (int) $day['absolute_day_number'] ?></span><small><?= $esc($day['availability'] === 'today' ? 'Today' : ucfirst($day['availability'])) ?> · <?= $esc($day['batch_title']) ?></small></a><?php endforeach; ?></aside><div class="revision-day-content"><?php foreach ($days as $day): $requirements = (array) ($day['requirements'] ?? []); foreach ((array) ($day['activity_groups'] ?? []) as $group) $requirements = array_merge($requirements, (array) ($group['requirements'] ?? [])); ?><section class="revision-day-panel <?= $day['availability'] === 'today' ? 'is-today' : '' ?> <?= !$day['accessible'] ? 'is-locked' : '' ?>" id="day-<?= (int) $day['absolute_day_number'] ?>"><header><div><span class="revision-student-card-kicker"><?= $esc($day['batch_title']) ?></span><h2>Day <?= (int) $day['absolute_day_number'] ?> · <?= $esc($day['title']) ?></h2><p><?= $esc(date('l, j M Y', strtotime((string) $day['scheduled_date']))) ?></p></div><span class="revision-day-status"><?= $esc($day['availability'] === 'today' ? 'Today' : ucfirst($day['availability'])) ?></span></header><?php if (!$day['accessible']): ?><div class="revision-locked-note"><span class="fas fa-lock" aria-hidden="true"></span> This day becomes available on <?= $esc(date('j M Y', strtotime((string) $day['scheduled_date']))) ?>.</div><?php else: ?><div class="revision-requirement-list"><?php foreach ($requirements as $requirement): ?><article class="revision-student-requirement"><div><span class="revision-requirement-type"><?= $esc(ucwords(str_replace('_', ' ', (string) $requirement['requirement_type']))) ?></span><h3><?= $esc($requirement['title']) ?></h3><?php if (($requirement['description'] ?? '') !== ''): ?><p><?= nl2br($esc($requirement['description'])) ?></p><?php endif; ?><?php if (!$requirement['is_required']): ?><small>Optional</small><?php endif; ?></div><div class="revision-requirement-action"><?php if ((string) $requirement['requirement_type'] === 'course_item' && trim((string) ($requirement['linked_course_item_id'] ?? '')) !== ''): ?><a class="student-dashboard-btn primary" href="<?= $esc($itemUrl((string) $requirement['linked_course_item_id'], (int) $requirement['id'])) ?>">Open Course Item</a><?php elseif ((string) $requirement['requirement_type'] === 'resource' && !empty($requirement['resource_ids'])): ?><div class="revision-resource-links"><?php foreach ((array) $requirement['resource_ids'] as $resourceId): if (!isset($resources[(int) $resourceId])) continue; ?><a class="student-dashboard-btn secondary" href="<?= $esc($resourceUrl((int) $resourceId, (int) $requirement['id'])) ?>"><span class="fas fa-file-alt" aria-hidden="true"></span><?= $esc($resources[(int) $resourceId]['display_name']) ?></a><?php endforeach; ?></div><?php elseif ((string) $requirement['requirement_type'] === 'upload'): ?><span class="revision-later-note">Submission will be available here in a later phase.</span><?php else: ?><span class="revision-later-note"><span class="fas fa-info-circle" aria-hidden="true"></span> Read-only checklist</span><?php endif; ?></div></article><?php endforeach; ?><?php if (!$requirements): ?><div class="revision-student-empty small"><p>No requirements have been added to this day yet.</p></div><?php endif; ?></div><?php endif; ?></section><?php endforeach; ?></div></div></section></main></div></body></html>
